text:
{
 "title": "特定B型肝炎ウイルス感染者給付金等支給特措法の改正",
 "lead": {
  "es": "B型肝炎《かたかんえん》ウイルスに感染《かんせん》した人《ひと》への給付金《きゅうふきん》を、請求《せいきゅう》できる期限《きげん》をのばした法律《ほうりつ》です。",
  "hs": "特定B型｜肝炎《かんえん》ウイルス感染者への給付金などを｜請求《せいきゅう》できる期限を、のばした法律です。",
  "std": "特定B型肝炎ウイルス感染者給付金等の請求期限を延長する等の法律です。",
  "univ": "特定Ｂ型肝炎ウイルス感染者給付金等の支給の請求の状況等を勘案し、当該給付金等の請求期限を延長する等の措置を講ずる法律。"
 },
 "facts": [
  {
   "es": "給付金《きゅうふきん》を請求《せいきゅう》できる期限《きげん》を、令和《れいわ》9年《ねん》3月《がつ》31日《にち》までにのばします。その日《ひ》までに裁判《さいばん》を起《お》こしたり、話《はな》し合《あ》いでの解決《かいけつ》を申《もう》しこんだりした人《ひと》は、判決《はんけつ》が決《き》まった日《ひ》などから1か月《げつ》たつ日《ひ》のほうがおそければ、その日《ひ》までになります。",
   "hs": "給付金の｜請求《せいきゅう》期限を、令和9年3月31日まで、またはそれまでに｜訴《うった》えや和解・調停の申し立てをした場合は、判決が確定した日や和解・調停が成立した日から1か月たつ日の、どちらかおそい日までにのばす。",
   "std": "給付金の請求期限を延長し、令和9年3月31日、又は同日以前に訴えの提起や和解・調停の申立てをした場合は判決確定日や和解・調停成立日から起算して1月を経過する日の、いずれか遅い日までとします。",
   "univ": "特定Ｂ型肝炎ウイルス感染者給付金の請求期限を延長し、令和9年3月31日又は訴えの提起若しくは和解若しくは調停の申立てを同日以前にした場合における当該訴えに係る判決が確定した日若しくは当該和解若しくは調停が成立した日から起算して1月を経過する日のいずれか遅い日までとする。"
  },
  {
   "es": "お金《かね》をはらう仕事《しごと》をする社会保険診療報酬支払基金《しゃかいほけんしんりょうほうしゅうしはらいききん》が、長《なが》い期間《きかん》お金《かね》を借《か》りられる期間《きかん》を、5年《ねん》のばします。",
   "hs": "社会保険｜診療《しんりょう》｜報酬《ほうしゅう》｜支払《しはらい》基金が長期でお金を借りられる期間を、5年のばす。",
   "std": "社会保険診療報酬支払基金の長期借入金について、借入れ可能期間を5年間延長します。",
   "univ": "社会保険診療報酬支払基金の長期借入金について、借入れ可能期間を5年間延長する。"
  },
  {
   "es": "政府《せいふ》は、令和《れいわ》9年《ねん》3月《がつ》31日《にち》までに、請求《せいきゅう》の様子《ようす》を見《み》て、必要《ひつよう》なら、給付金《きゅうふきん》のお金《かね》をどう用意《ようい》するかを考《かんが》え、そのとおりにします。",
   "hs": "政府は、令和9年3月31日までの間に、｜請求《せいきゅう》の｜状況《じょうきょう》を見て必要なら、給付金などの費用の財源の確保のしかたを検討し、その結果にもとづいて｜措置《そち》をとる。",
   "std": "政府は、令和9年3月31日までの間に、請求の状況を勘案し、必要があると認めるときは、給付金等の支給に要する費用の財源確保の在り方を検討し、その結果に基づいて措置を講じます。",
   "univ": "政府は、令和9年3月31日までの間において、特定Ｂ型肝炎ウイルス感染者給付金等の支給の請求の状況を勘案し、必要があると認めるときは、その支給に要する費用の財源の確保の在り方について検討を加え、その結果に基づいて所要の措置を講ずる。"
  },
  {
   "es": "この法律《ほうりつ》は、出《だ》された日《ひ》から使《つか》われます。",
   "hs": "この法律は、公布の日から｜施行《しこう》する。",
   "std": "公布の日から施行します。",
   "univ": "この法律は、公布の日から施行する。"
  }
 ]
}
